// 1. Получаем последние 7 дней из узла Get day_sum
const dayRows = $('Get day_sum').all().map(r => r.json)
  .filter(r => r['Date'])
  .sort((a, b) => (a['Date'] < b['Date']) ? 1 : (a['Date'] > b['Date']) ? -1 : 0)
  .slice(0, 7);

// 2. Получаем цели из узла Get Nutrient_Targets
const targets = $('Get Nutrient_Targets').all().map(r => r.json);

// Вспомогательная функция для безопасного парсинга чисел
function parseNum(v) {
  if (!v) return null;
  const m = String(v).match(/-?\d+(?:[.,]\d+)?/);
  return m ? parseFloat(m[0].replace(',', '.')) : null;
}

const deficits = [];
const excesses = [];

// 3. Вычисляем среднее за неделю по каждому нутриенту
targets.forEach(t => {
  const col = t['Колонка_в_Meals'];
  if (!col) return;

  const rda = parseNum(t['Норма_RDA_AI']);
  const ul = parseNum(t['Верхний_предел_UL']);
  const isLimitType = (t['Категория'] || '').includes('Риск избытка');

  let sum = 0;
  let count = 0;

  dayRows.forEach(r => {
    const val = parseFloat(String(r[col]).replace(',', '.'));
    if (!isNaN(val)) {
      sum += val;
      count++;
    }
  });

  if (count === 0) return;
  const avg = sum / count;

  // 4. Сортируем на дефициты и профициты
  if (isLimitType && ul && avg > ul) {
     excesses.push(`- ${t['Нутриент']}: в среднем ${Math.round(avg)} (лимит ${ul})`);
  } else if (!isLimitType && rda && avg < rda * 0.85) {
     // Считаем дефицитом всё, что ниже 85% от цели
     deficits.push(`- ${t['Нутриент']}: в среднем ${Math.round(avg)} (норма ${rda})`);
  }
});

// 5. Формируем контекст для LLM
const promptContext = `
Анализ питания за последние 7 дней:

КРИТИЧЕСКИЕ ДЕФИЦИТЫ (нужно восполнить):
${deficits.length > 0 ? deficits.join('\n') : 'Дефицитов не обнаружено. Поддерживай текущий баланс.'}

ПРОФИЦИТЫ / ИЗБЫТОК (нужно компенсировать/сократить):
${excesses.length > 0 ? excesses.join('\n') : 'Избытка токсичных нутриентов нет.'}

Локальный контекст ингредиентов: в приоритете дикая рыба, дальневосточные морепродукты (кальмар, гребешок, мидии), птица, свежие овощи. Из жиров активно используются масло авокадо и льняной урбеч.
`;

return [{ 
  json: { 
    llm_prompt: promptContext, 
    deficits_count: deficits.length,
    excesses_count: excesses.length
  } 
}];

const __t = ($input.first().json.query || {}).token;
if (__t !== 'Bz8nnNaltVyeUKfVLy71') return [{ json: { error: 'forbidden' } }];
// Ветка Webhook в том же workflow, что и Schedule Trigger → ... → AI Agent → Code (пишет).
// Static Data общая на весь workflow.

const staticData = $getWorkflowStaticData('global');
const cached = staticData.recipes;

if (!cached) {
  return [{
    json: {
      error: 'no_data_yet',
      message: 'Рецепты ещё не сгенерированы. Дождитесь первого запуска по расписанию.'
    }
  }];
}

return [{ json: cached }];

// Достаём текст, который сгенерировал AI Agent
const aiText = $input.first().json.output;

const staticData = $getWorkflowStaticData('global');
staticData.recipes = {
  updated_at: new Date().toISOString(),
  recipes: aiText
};

return [{ json: staticData.recipes }];

